@app.route('/history')
def history():
    """Dynamically generates the history page by reading `note_reports.json`."""
    history_data = []
    if os.path.exists(JSON_INPUT_FILE):
        try:
            with open(JSON_INPUT_FILE, 'r', encoding='utf-8') as f:
